<!DOCTYPE html><html lang="en" data-theme="auto" data-active-theme="light"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{{ $project->short_description }}"><title>{{ $project->title }} | zyuruEntertainment</title><script>(()=>{let t='auto';try{t=localStorage.getItem('zyuru-theme')||'auto'}catch{}const d=matchMedia('(prefers-color-scheme: dark)').matches;const a=t==='auto'?(d?'dark':'light'):t;document.documentElement.dataset.theme=t;document.documentElement.dataset.activeTheme=a;document.documentElement.style.colorScheme=a})();</script><link rel="stylesheet" href="{{ asset('css/style.css') }}"><link rel="stylesheet" href="{{ asset('css/projects.css') }}"></head><body><div class="site-shell"><header class="header"><a class="wordmark" href="{{ url('/') }}">zyuruEntertainment</a><button class="theme-toggle" id="themeToggle" type="button" aria-label="Switch color theme">◐</button></header><main class="project-detail"><section><p class="eyebrow">{{ $project->status }}</p><h1>{{ $project->title }}</h1><p class="project-lead">{{ $project->short_description }}</p><div class="project-full-description">{{ $project->full_description }}</div><div class="form-actions"><a class="ghost-button" href="{{ route('projects') }}">Back to Projects</a><a class="primary-button" href="{{ $project->github_url }}" target="_blank" rel="noopener noreferrer">View on GitHub</a></div></section>@if($project->preview_path)<aside class="project-detail-media">@if($project->preview_type==='video')<video src="{{ asset('storage/'.$project->preview_path) }}" controls playsinline></video>@else<img src="{{ asset('storage/'.$project->preview_path) }}" alt="{{ $project->title }} preview">@endif</aside>@endif</main><footer class="footer"><span>© <span id="year">2026</span> zyuruEntertainment</span><span class="footer-label">GAMES <i></i> SOFTWARE <i></i> TECHNOLOGY</span></footer></div><script>const r=document.documentElement,t=